const isObj = (v: unknown): v is Record<string, unknown> => !!v && typeof v === 'object' && !Array.isArray(v);

// ─── the game document (project, game.json, runtime spec) ───────────────────

/** The tick of game.engine in a project's `installed` list: `null` when game.engine is not installed. */
export function engineTickOf(installed: unknown): { installed: boolean; hz: number | null } {
  if (!Array.isArray(installed)) return { installed: false, hz: null };
  const engine = installed.find((k) => isObj(k) && k.id === 'game.engine' && k.enabled !== false) as Record<string, unknown> | undefined;
  if (!engine) return { installed: false, hz: null };
  const tick = isObj(engine.config) ? engine.config.tick : undefined;
  const hz = isObj(tick) && typeof tick.hz === 'number' && Number.isFinite(tick.hz) ? tick.hz : null;
  return { installed: true, hz };
}

/** The reasons a game document states, by rule (`coreLoopReasons` at its root, in its `schema` or its `project`). */
function reasonsOf(doc: Record<string, unknown>): Record<string, string> {
  const out: Record<string, string> = {};
  const take = (v: unknown) => { if (isObj(v)) for (const [k, r] of Object.entries(v)) if (typeof r === 'string' && r.trim()) out[k] = r; };
  take(doc.coreLoopReasons);
  if (isObj(doc.schema)) take(doc.schema.coreLoopReasons);
  if (isObj(doc.project)) { take(doc.project.coreLoopReasons); if (isObj(doc.project.schema)) take(doc.project.schema.coreLoopReasons); }
  return out;
}

/**
 * The checks of a game document (a Game Kit project, an exported game.json, a runtime spec): the explicit tick, and
 * the threads it refuses (memory shared:false, physics placement main, playerWorker 0) without a stated reason.
 */
export function checkCoreLoopDocument(doc: unknown, file?: string): CoreLoopIssue[] {
  if (!isObj(doc)) return [];
  const out: CoreLoopIssue[] = [];
  const reasons = reasonsOf(doc);
  const at = file ? { file } : undefined;
  const seen = new Set<string>();
  const walk = (v: unknown, path: string, depth: number) => {
    if (depth > 12) return;
    if (Array.isArray(v)) { v.forEach((x, i) => walk(x, `${path}[${i}]`, depth + 1)); return; }
    if (!isObj(v)) return;
    if (Array.isArray(v.installed)) {
      const t = engineTickOf(v.installed);
      if (t.installed && t.hz === null && !seen.has('tick')) { seen.add('tick'); out.push(issue('tick_missing', `${path ? `${path}.` : ''}installed game.engine config has no tick.hz`, at)); }
    }
    for (const [k, x] of Object.entries(v)) {
      const here = path ? `${path}.${k}` : k;
      if (k === 'memory' && isObj(x) && x.shared === false && !reasons.shared_memory_disabled && !(typeof x.reason === 'string' && x.reason.trim())) out.push(issue('shared_memory_disabled', `${here}.shared: false`, at));
      if (k === 'placement' && x === false && !reasons.physics_main_thread) out.push(issue('physics_main_thread', `${here}: false places every module, physics included, on the main thread`, at));
      if (k === 'placement' && isObj(x)) for (const [m, p] of Object.entries(x)) if (/^physics(\.|$)/.test(m) && p === 'main' && !reasons.physics_main_thread) out.push(issue('physics_main_thread', `${here}["${m}"]: "main"`, at));
      if (k === 'playerWorker' && (x === 0 || x === false || x === '0' || x === 'false' || x === 'off') && !reasons.worker_disabled) out.push(issue('worker_disabled', `${here}: ${JSON.stringify(x)}`, at));
      if (k !== 'coreLoopReasons') walk(x, here, depth + 1);
    }
  };
  walk(doc, '', 0);
  return out;
}

