/** The source with its comments (and, for C-like languages, its string contents) blanked, lines kept. */
function blank(text: string, lang: Lang): string {
  let out = '';
  const hash = lang === 'gd';
  for (let i = 0; i < text.length; i++) {
    const c = text[i]!, n = text[i + 1];
    if (hash && c === '#') { while (i < text.length && text[i] !== '\n') { out += ' '; i++; } out += text[i] ?? ''; continue; }
    if (!hash && c === '/' && n === '/') { while (i < text.length && text[i] !== '\n') { out += ' '; i++; } out += text[i] ?? ''; continue; }
    if (!hash && c === '/' && n === '*') { out += '  '; i += 2; while (i < text.length && !(text[i] === '*' && text[i + 1] === '/')) { out += text[i] === '\n' ? '\n' : ' '; i++; } out += '  '; i++; continue; }
    out += c;
  }
  return out;
}

interface Body { name: string; start: number; end: number }

/** The bodies of the functions named `names` (brace languages): from the `{` after the header to its match. */
function braceBodies(code: string, names: string[], lang: Lang): Body[] {
  if (!names.length) return [];
  const out: Body[] = [];
  const alt = names.map((n) => n.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|');
  // `fn update(`, `void Update(`, `update(dt) {`, `update: function (`, `update = (dt) => {`, `::Tick(`.
  const header = lang === 'rs' ? new RegExp(`\\bfn\\s+(${alt})\\s*[<(]`, 'g')
    : new RegExp(`(?:^|[^\\w.$])(${alt})\\s*(?:[:=]\\s*(?:async\\s*)?(?:function\\s*)?)?\\(`, 'g');
  let m: RegExpExecArray | null;
  while ((m = header.exec(code))) {
    // The header ends at the `{` that opens the body; a `;` first means a call or a declaration.
    let i = m.index + m[0].length, depth = 1;
    while (i < code.length && depth > 0) { if (code[i] === '(') depth++; else if (code[i] === ')') depth--; i++; }
    let j = i;
    while (j < code.length && /[\s\w:&<>,'=>\-*.?!\[\]]/.test(code[j]!) && code[j] !== '{' && code[j] !== ';') j++;
    if (code[j] !== '{') continue;
    const between = code.slice(i, j);
    if (lang === 'js' && between.trim() && !/^(?::[^=]*)?(?:=>)?\s*$/.test(between.trim())) continue;
    let d = 0, k = j;
    for (; k < code.length; k++) { if (code[k] === '{') d++; else if (code[k] === '}') { d--; if (d === 0) break; } }
    out.push({ name: m[1]!, start: j, end: k });
    header.lastIndex = j + 1;
  }
  return out;
}

/** The bodies of the GDScript functions named `names`: the lines indented under `func name(`. */
function gdBodies(code: string, names: string[]): Body[] {
  const out: Body[] = [];
  const lines = code.split('\n');
  let offset = 0;
  const starts = lines.map((l) => { const s = offset; offset += l.length + 1; return s; });
  for (let i = 0; i < lines.length; i++) {
    const m = /^(\s*)(?:static\s+)?func\s+(\w+)\s*\(/.exec(lines[i]!);
    if (!m || !names.includes(m[2]!)) continue;
    const indent = m[1]!.length;
    let j = i + 1;
    while (j < lines.length && (!lines[j]!.trim() || (/^\s*/.exec(lines[j]!)![0].length > indent))) j++;
    out.push({ name: m[2]!, start: starts[i]!, end: (starts[j - 1] ?? starts[i]!) + (lines[j - 1]?.length ?? 0) });
  }
  return out;
}

/** The bodies of the callbacks given to requestAnimationFrame (inline, or a named function of the file). */
function rafBodies(code: string): Body[] {
  const out: Body[] = [];
  const re = /requestAnimationFrame\s*\(\s*([A-Za-z_$][\w$]*)?/g;
  let m: RegExpExecArray | null;
  const named = new Set<string>();
  while ((m = re.exec(code))) {
    if (m[1] && m[1] !== 'function' && m[1] !== 'async') { named.add(m[1]); continue; }
    const open = code.indexOf('{', m.index);
    const close = code.indexOf(')', m.index + m[0].length);
    if (open < 0 || (close >= 0 && close < open && !/=>\s*$/.test(code.slice(m.index, open)))) continue;
    let d = 0, k = open;
    for (; k < code.length; k++) { if (code[k] === '{') d++; else if (code[k] === '}') { d--; if (d === 0) break; } }
    out.push({ name: 'requestAnimationFrame', start: open, end: k });
  }
  if (named.size) out.push(...braceBodies(code, [...named], 'js').map((b) => ({ ...b, name: `requestAnimationFrame(${b.name})` })));
  return out;
}

/**
 * The checks of one source file (a game script, a kit's code, a page): game state written by a frame hook, gameplay in
 * a physics callback, the engine physics step retuned, a tick path that waits, the threads turned off without reason.
 */
export function checkCoreLoopSource(file: string, text: string): CoreLoopIssue[] {
  const lang = coreLoopLanguage(file);
  if (!lang || text.length > 4 * 1024 * 1024) return [];
  const raw = text.split('\n');
  const code = blank(text, lang);
  const lineOf = (index: number) => code.slice(0, index).split('\n').length;
  const reasoned = (line: number) => raw[line - 1]?.includes(CORE_LOOP_REASON_MARK) || raw[line - 2]?.includes(CORE_LOOP_REASON_MARK);
  const out: CoreLoopIssue[] = [];
  const seen = new Set<string>();
  const push = (rule: CoreLoopRuleId, what: string, index: number) => {
    const line = lineOf(index);
    if (CORE_LOOP_RULES[rule].reasonable && reasoned(line)) return;
    const key = `${rule}:${line}`;
    if (seen.has(key)) return;
    seen.add(key);
    out.push(issue(rule, what, { file, line }));
  };
  // The thread switches: in the code (comments blanked) of any page or script.
  if (lang === 'js' || lang === 'html') for (const s of SWITCHES) {
    const re = new RegExp(s.re.source, 'g');
    let m: RegExpExecArray | null;
    while ((m = re.exec(code))) push(s.rule, m[0].replace(/\s+/g, ' ').slice(0, 60), m.index);
  }
  if (lang === 'html') return out;
  const hooks = HOOKS[lang];
  const bodies = (names: string[]) => (lang === 'gd' ? gdBodies(code, names) : braceBodies(code, names, lang));
  const scan = (body: Body, res: RegExp[], rule: CoreLoopRuleId, where: string) => {
    const part = code.slice(body.start, body.end);
    for (const re of res) {
      const g = new RegExp(re.source, re.flags.includes('g') ? re.flags : `${re.flags}g`);
      let m: RegExpExecArray | null;
      while ((m = g.exec(part))) push(rule, `${m[0].trim().slice(0, 48)} in ${where}`, body.start + m.index);
    }
  };
  const frames = [...bodies(hooks.frame), ...(lang === 'js' ? rafBodies(code) : [])];
  for (const b of frames) scan(b, MUTATES[lang], 'frame_mutates_state', `${b.name}()`);
  for (const b of bodies(hooks.physics)) { scan(b, MUTATES[lang], 'physics_runs_gameplay', `${b.name}()`); scan(b, [STEPS_TICK], 'physics_runs_gameplay', `${b.name}() steps the game tick`); }
  for (const b of bodies(hooks.tick)) scan(b, WAITS[lang], 'sync_worker_call', `${b.name}()`);
  for (const re of RETUNES[lang] ?? []) {
    const g = new RegExp(re.source, 'g');
    let m: RegExpExecArray | null;
    while ((m = g.exec(code))) push('engine_physics_retuned', m[0].trim().slice(0, 48), m.index);
  }
  return out;
}

/** The checks of a set of files: sources by language, JSON documents as game documents. */
export function checkCoreLoopFiles(files: ReadonlyArray<{ path: string; text: string }>): CoreLoopIssue[] {
  const out: CoreLoopIssue[] = [];
  for (const f of files) {
    if (/\.json$/i.test(f.path)) {
      let doc: unknown;
      try { doc = JSON.parse(f.text); } catch { continue; }
      out.push(...checkCoreLoopDocument(doc, f.path));
    } else out.push(...checkCoreLoopSource(f.path, f.text));
  }
  return out;
}

/** One line per issue, then its fix: what the CLI prints. */
export function coreLoopSummary(issues: readonly CoreLoopIssue[]): string {
  if (!issues.length) return 'Core loop: OK (tick set, frame and physics hooks read only, no thread waits, workers on).';
  return [`Core loop: ${issues.length} problem${issues.length > 1 ? 's' : ''} (docs/game-engine-contract.md §12).`, ...issues.map((i) => `- [${i.code}] ${i.message}\n  Fix: ${i.fix}`)].join('\n');
}

/** Folders never read as the game's own code: dependencies, builds, caches, and the GripForge adapters themselves. */
export const CORE_LOOP_SKIP_DIRS = ['node_modules', 'target', 'build', 'dist', 'Library', 'Temp', 'Logs', 'obj', 'Binaries', 'Intermediate', 'DerivedDataCache', 'Saved', 'gripforge_kits', 'GripForgeKits', 'player', 'modules', 'vendor', 'third_party'];

/** What a folder walk needs (node:fs synchronous calls, given by the caller so this file stays dependency-free). */
export interface CoreLoopFs {
  readdir(path: string): string[];
  isDirectory(path: string): boolean;
  size(path: string): number;
  read(path: string): string;
}

/**
 * The game's files under `root` that the rule reads: its sources (by language) and its JSON game documents
 * (`game.json`, `*.project.json`, `gripforge*.json`), the folders of CORE_LOOP_SKIP_DIRS left out. At most `max` files.
 */
export function collectCoreLoopFiles(root: string, fs: CoreLoopFs, max = 3000): Array<{ path: string; text: string }> {
  const out: Array<{ path: string; text: string }> = [];
  const walk = (dir: string, rel: string, depth: number) => {
    if (depth > 10 || out.length >= max) return;
    let names: string[] = [];
    try { names = fs.readdir(dir); } catch { return; }
    for (const name of names.sort()) {
      if (out.length >= max) return;
      if (name.startsWith('.') || CORE_LOOP_SKIP_DIRS.includes(name) || /^com\.gripforge/.test(name)) continue;
      const path = `${dir}/${name}`, r = rel ? `${rel}/${name}` : name;
      let directory = false;
      try { directory = fs.isDirectory(path); } catch { continue; }
      if (directory) { walk(path, r, depth + 1); continue; }
      const json = /(^game\.json|\.project\.json|^gripforge[\w.-]*\.json)$/i.test(name);
      if (!json && !coreLoopLanguage(name)) continue;
      try { if (fs.size(path) <= 4 * 1024 * 1024) out.push({ path: r, text: fs.read(path) }); } catch { /* unreadable: skipped */ }
    }
  };
  walk(root.replace(/\/+$/, ''), '', 0);
  return out;
}
